from taf.ul.ettf.context import context
from taf.ul.ettf.scheduler.base_listeners import SuiteListener
from taf.ul.ettf.sim.core.simulator_provider import simulator_provider


class simulator_provider_listener(SuiteListener):
    def __init__(self):
        super(simulator_provider_listener, self).__init__()
        context.change_simulator(simulator_provider().get_simulator())
